// Read what mode we are being called in
boolean securityCheck = tools.getParamAsBoolean(PropertyInfo.TYPE_TRUEFALSE, "FieldLevelSecurityCheck");
boolean debugging = pega_rules_utilities.getDataSystemSetting("Pega-API", "DebugPegaAPI").equalsIgnoreCase("true");

// Let's read pyInstruction and pyTarget first; they must always be present.
String instruction = myStepPage.getString(".instruction");
if (instruction.equals(""))
{
	tools.putParamValue("ErrorMessage", "Instruction not specified");
	return false;		
}
String target = myStepPage.getString(".target");
if (target.equals(""))
{
	tools.putParamValue("ErrorMessage", "Target not specified for instruction " + instruction);
	return false;		
}
if (target.charAt(0) != '.')
	target = "." + target;

// The target may be a deeply nested reference like .myPageList(3).myInnerPageList(2).myEmbeddedPage; let's get a reference to it and identify what type of page it is.
// We need to catch IndexOutOfBoundsException because the list indices passed in, like the 3 and 2 above, may exceed the size of the list on the case.
// Also, if we are checking field security, we need to alter any pagelist indices in the target path to 1
if (securityCheck && target.indexOf("(") > 0)
{
	StringBuffer revisedTarget = new StringBuffer();
	boolean isSubscript = false;
	String[] targetParts = target.split("[\\(||\\)]");
	for (int i=0; i < targetParts.length; i++)
	{
		String targetPart = targetParts[i];
		if (isSubscript)
		{
			// This is a subscript of a pagelist or pagegroup.  It could be a pagelist index or a pagegroup subscript.  We only want to change pagelist indices to 1.
			try {
				int x = Integer.parseInt(targetPart);
				targetPart = "1";
			} catch (NumberFormatException nfe) {
				// it's not a number, so leave it as is
			}
			revisedTarget.append("(" + targetPart + ")");
		}
		else {
			revisedTarget.append(targetPart);
		}
		isSubscript = !isSubscript;
	}
	if (debugging)
		oLog.infoForced("Converting target " + target + " to " + revisedTarget.toString() + " for field security check on the request page.");
	target = revisedTarget.toString();
}

if (debugging)
{
  if (securityCheck)
    oLog.infoForced("Applying " + instruction + " for " + target + " on the request page.");
  else
    oLog.infoForced("Applying " + instruction + " for " + target + " on the case.");  
}

ClipboardProperty targetPageRef;
try {
	targetPageRef = tools.getPrimaryPage().getProperty(target);
} catch (java.lang.IndexOutOfBoundsException ibe) {
	if (securityCheck)
		tools.putParamValue("ErrorMessage", ibe.getMessage() + " for target " + target + " on the request page.");
	else	
		tools.putParamValue("ErrorMessage", ibe.getMessage() + " for target " + target + " on the case.");
	return false;
} catch (InvalidReferenceException ire) {
	if (securityCheck)
		tools.putParamValue("ErrorMessage", ire.getMessage() + " for target " + target + " on the request page.");
	else	
		tools.putParamValue("ErrorMessage", ire.getMessage() + " for target " + target + " on the case.");	
	return false;	
}
char targetPageMode = targetPageRef.getMode();

if (targetPageMode == ImmutablePropertyInfo.MODE_PAGE)
{
  ClipboardPage pgTarget = targetPageRef.getPageValue();
  switch (instruction)
  {
    case "DELETE":
	  if (!securityCheck)
		targetPageRef.removeFromClipboard();
      break;      
    case "REPLACE":
      pgTarget.clear();
	  if (!securityCheck)
		tools.applyModel(pgTarget, null, "pyDefault");  // account for read-only and non-form fields
    case "UPDATE":
      // Get the content we are updating
      ClipboardProperty contentToMergeRef = myStepPage.getProperty(".content");
      ClipboardPage pgMergeContent = contentToMergeRef.getPageValue();
      pgTarget.putAll(pgMergeContent, ClipboardPage.PUTALL_KEEPNEW);
      break;
    default:
      // Illegal instruction error
      tools.putParamValue("ErrorMessage", "Illegal instruction for an embedded page: '" + instruction + "'");
  }

}
else if (targetPageMode == ImmutablePropertyInfo.MODE_PAGE_LIST)
{
  if (securityCheck)
  {
	  // Add one dummy page into the pagelist, because the pagelist won't actually be there to start with
	  String pagelistClass = tools.getDictionary().fromDefinition(targetPageRef, "pyPageClass");
	  ClipboardPage tempPage = tools.createPage(pagelistClass, "");
	  targetPageRef.add(tempPage);
  }

  if (instruction.equals("APPEND"))
  {
    // We handle APPEND separately from the others because it is the only one that doesn't use a listIndex
    ClipboardProperty contentToMergeRef = myStepPage.getIfPresent(".content");
	if (contentToMergeRef == null) {
		tools.putParamValue("ErrorMessage", "Content not found for APPEND to pagelist: '" + target + "'");		
		return false;
	}
    ClipboardPage pgMergeContent = contentToMergeRef.getPageValue(); 
    targetPageRef.add(pgMergeContent);

	if (!securityCheck)
	{
		// Now merge into the newly appended page the pyDefault data transform to capture read-only and non-form fields
		ClipboardPage newlyAppendedRow = targetPageRef.getPageValue(targetPageRef.size());
		ClipboardPage myTempPage = tools.createPage(newlyAppendedRow.getClassName(), "");
		tools.applyModel(myTempPage, null, "pyDefault");
		newlyAppendedRow.putAll(myTempPage, ClipboardPage.PUTALL_MODEL); 
	}	
  }
  else 
  {
	  // All the other pagelist instructions require a listIndex.
	if (myStepPage.getIfPresent(".listIndex") == null)
	{
		tools.putParamValue("ErrorMessage", "Instruction " + instruction + " for pagelist: '" + target + "' requires a listIndex.");
		return false;
	}
    int listIndex = myStepPage.getInteger(".listIndex");

	if (securityCheck)
		listIndex = 1;  // for field level security checking, just do all non-Append operations against the first dummy row

    ClipboardProperty targetPageListRef;
    try {
      targetPageListRef = targetPageRef.getPropertyValue(listIndex);
    } catch (IndexOutOfBoundsException ioe) {
      tools.putParamValue("ErrorMessage", ioe.getMessage());
      return false;
    }
    ClipboardPage pgTarget = targetPageListRef.getPageValue();
    ClipboardProperty contentToMergeRef;
    ClipboardPage pgMergeContent;

    switch (instruction)
    {
      case "DELETE":
		if (!securityCheck)
			targetPageRef.remove(listIndex);
        break;      
      case "REPLACE":
        pgTarget.clear();
		if (!securityCheck)
			tools.applyModel(pgTarget, null, "pyDefault");  // account for read-only and non-form fields
      case "UPDATE":
        // Get the content we are updating
        contentToMergeRef = myStepPage.getIfPresent(".content");
		if (contentToMergeRef == null) {
			tools.putParamValue("ErrorMessage", "Content not found for " + instruction + " to pagelist: '" + target + "'");		
			return false;
		}
        pgMergeContent = contentToMergeRef.getPageValue();
        pgTarget.putAll(pgMergeContent, ClipboardPage.PUTALL_KEEPNEW);
        break;     
      case "INSERT":
        contentToMergeRef = myStepPage.getIfPresent(".content");
		if (contentToMergeRef == null) {
			tools.putParamValue("ErrorMessage", "Content not found for INSERT to pagelist: '" + target + "'");		
			return false;
		}		
        pgMergeContent = contentToMergeRef.getPageValue();       
        targetPageRef.add(listIndex, pgMergeContent);

		if (!securityCheck)
		{
			// Now merge into the newly inserted page the pyDefault data transform to capture read-only and non-form fields
			ClipboardPage newlyAppendedRow = targetPageRef.getPageValue(listIndex);
			ClipboardPage myTempPage = tools.createPage(newlyAppendedRow.getClassName(), "");
			tools.applyModel(myTempPage, null, "pyDefault");
			newlyAppendedRow.putAll(myTempPage, ClipboardPage.PUTALL_MODEL);
		}		
        break;
      case "MOVE":
	  	if (securityCheck)
			// No need to do a move if just checking field level security
			break;

        // First we remove the row, then we insert it back
        ClipboardProperty rowBeingMoved = (ClipboardProperty)targetPageRef.remove(listIndex);
		if (myStepPage.getIfPresent(".listMoveToIndex") == null)
		{
			tools.putParamValue("ErrorMessage", "Instruction MOVE for pagelist: '" + target + "' requires a listMoveToIndex.");			
			return false;
		}
        int listMoveToIndex = myStepPage.getInteger(".listMoveToIndex");
        targetPageRef.add(listMoveToIndex, rowBeingMoved.getPageValue());
        break;
      default:
        // Illegal instruction error
        tools.putParamValue("ErrorMessage", "Illegal instruction '" + instruction + "' for pagelist: '" + target + "'");
    }  
  }    
}
else if (targetPageMode == ImmutablePropertyInfo.MODE_PAGE_GROUP)
{
	// unlike pagelists, all pagegroup instructions require a groupIndex field to be present.
	if (myStepPage.getIfPresent(".groupIndex") == null)
	{
		tools.putParamValue("ErrorMessage", "Instruction " + instruction + " for pagegroup: '" + target + "' requires a groupIndex.");
		return false;
	}	
	String groupIndex = myStepPage.getString(".groupIndex");	
  ClipboardProperty targetPageGroupRef = tools.getPrimaryPage().getIfPresent(target + "(" + groupIndex + ")");
	if (instruction.equals("ADD"))
	{
		// We handle ADD separately from the others because it is the only one that doesn't expect the groupIndex to exist beforehand
		if (!securityCheck && targetPageGroupRef != null) {
			tools.putParamValue("ErrorMessage", "Subscript '" + groupIndex + "' already exists in pagegroup '" + target + "'");
			return false;
		}

		ClipboardProperty contentToMergeRef = myStepPage.getIfPresent(".content");
		if (contentToMergeRef == null) {
			tools.putParamValue("ErrorMessage", "Content not found for ADD to pagegroup: '" + target + "'");		
			return false;
		}		
		ClipboardPage pgMergeContent = contentToMergeRef.getPageValue(); 
		targetPageRef.add(groupIndex, pgMergeContent);

		if (!securityCheck)
		{
			// Now merge into the newly added page the pyDefault data transform to capture read-only and non-form fields
			ClipboardPage newlyAddedRow = targetPageRef.getPageValue(groupIndex);
			ClipboardPage myTempPage = tools.createPage(newlyAddedRow.getClassName(), "");
			tools.applyModel(myTempPage, null, "pyDefault");
			newlyAddedRow.putAll(myTempPage, ClipboardPage.PUTALL_MODEL);  
		}		
	}
	else 
	{
		if (targetPageGroupRef == null)
		{
			if (securityCheck)
			{
				// Just add it since we're just doing the field security check
				String pagelistClass = tools.getDictionary().fromDefinition(targetPageRef, "pyPageClass");
				ClipboardPage tempPage = tools.createPage(pagelistClass, "");
				targetPageRef.add(groupIndex, tempPage);
				targetPageGroupRef = targetPageRef.getPropertyValue(groupIndex);
			}
			else {
				tools.putParamValue("ErrorMessage", "Subscript '" + groupIndex + "' does not exist for pagegroup '" + target + "' with instruction " + instruction);
				return false;
			}
		}

		ClipboardPage pgTarget = targetPageGroupRef.getPageValue();
		ClipboardProperty contentToMergeRef;
		ClipboardPage pgMergeContent;

		switch (instruction)
		{
		  case "DELETE":
			if (!securityCheck)
				targetPageRef.remove(groupIndex);
			break;      
		  case "REPLACE":
			pgTarget.clear();
			if (!securityCheck)
				tools.applyModel(pgTarget, null, "pyDefault");  // account for read-only and non-form fields
		  case "UPDATE":
			// Get the content we are updating
			contentToMergeRef = myStepPage.getIfPresent(".content");
			if (contentToMergeRef == null) {
				tools.putParamValue("ErrorMessage", "Content not found for " + instruction + " to pagegroup: '" + target + "'");		
				return false;
			}
			pgMergeContent = contentToMergeRef.getPageValue();
			pgTarget.putAll(pgMergeContent, ClipboardPage.PUTALL_KEEPNEW);
			break;     
		  default:
			// Illegal instruction error
			tools.putParamValue("ErrorMessage", "Illegal instruction '" + instruction + "' for target pagegroup: '" + target + "'");
		}  
	}    
}
else if (targetPageMode == ImmutablePropertyInfo.MODE_UNKNOWN)
{
  // error; not an identifiable property
  tools.putParamValue("ErrorMessage", "Target '" + target + "' has an unknown property mode.");
}
else {
  // error; not a page at all!
  tools.putParamValue("ErrorMessage", "Target '" + target + "' is not an embedded page of any kind.");
}
